package health_test

import (
	"context"
	"encoding/json"
	"errors"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/gin-gonic/gin"
	"github.com/mbashem/cftracker/backend/internal/health"
	"github.com/mbashem/cftracker/backend/internal/routes"
)

const (
	testReadinessTimeout = time.Second
	testEarlierDeadline  = 20 * time.Millisecond
)

type requestContextKey struct{}

type healthResponse struct {
	Status string `json:"status"`
}

// Generated by Codex and not thoroughly checked for correctness.
func TestLivenessDoesNotDependOnDatabase(t *testing.T) {
	for _, testCase := range []struct {
		name     string
		database *mockDatabase
	}{
		{name: "no database is configured"},
		{name: "database is unavailable", database: &mockDatabase{err: errors.New("private database failure")}},
		{name: "database is blocked", database: &mockDatabase{waitForCancellation: true}},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			response := performHealthRequest(t.Context(), newHealthRouter(testCase.database), "/health/live")
			assertHealthResponse(t, response, http.StatusOK, "alive")
			if testCase.database != nil && testCase.database.called {
				t.Fatal("liveness contacted the database")
			}
		})
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestReadinessChecksDatabaseWithRequestContextAndDeadline(t *testing.T) {
	for _, testCase := range []struct {
		name             string
		database         *mockDatabase
		cancelRequest    bool
		earlierDeadline  bool
		wantHTTPStatus   int
		wantStatus       string
		wantContextError error
	}{
		{name: "connected database is ready", database: &mockDatabase{}, wantHTTPStatus: http.StatusOK, wantStatus: "ready"},
		{name: "database failure is unavailable without exposing details", database: &mockDatabase{err: errors.New("password=private database detail")}, wantHTTPStatus: http.StatusServiceUnavailable, wantStatus: "unavailable"},
		{name: "missing database is unavailable", wantHTTPStatus: http.StatusServiceUnavailable, wantStatus: "unavailable"},
		{name: "blocked database stops at readiness deadline", database: &mockDatabase{waitForCancellation: true}, wantHTTPStatus: http.StatusServiceUnavailable, wantStatus: "unavailable", wantContextError: context.DeadlineExceeded},
		{name: "canceled request cancels the database check", database: &mockDatabase{waitForCancellation: true}, cancelRequest: true, wantHTTPStatus: http.StatusServiceUnavailable, wantStatus: "unavailable", wantContextError: context.Canceled},
		{name: "earlier request deadline takes precedence", database: &mockDatabase{waitForCancellation: true}, earlierDeadline: true, wantHTTPStatus: http.StatusServiceUnavailable, wantStatus: "unavailable", wantContextError: context.DeadlineExceeded},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			ctx := context.WithValue(t.Context(), requestContextKey{}, testCase.name)
			ctx, cancel := context.WithCancel(ctx)
			defer cancel()
			if testCase.cancelRequest {
				cancel()
			}
			if testCase.earlierDeadline {
				deadlineContext, cancelDeadline := context.WithTimeout(ctx, testEarlierDeadline)
				defer cancelDeadline()
				ctx = deadlineContext
			}
			response := performHealthRequest(ctx, newHealthRouter(testCase.database), "/health/ready")
			assertHealthResponse(t, response, testCase.wantHTTPStatus, testCase.wantStatus)
			if testCase.database == nil {
				return
			}
			mock := testCase.database
			if !mock.called || mock.ctx.Value(requestContextKey{}) != testCase.name {
				t.Fatal("database check did not receive the request context")
			}
			deadline, bounded := mock.ctx.Deadline()
			if !bounded || deadline.After(mock.started.Add(testReadinessTimeout)) {
				t.Fatalf("database deadline = %v, bounded = %v", deadline, bounded)
			}
			if testCase.earlierDeadline {
				requestDeadline, _ := ctx.Deadline()
				if !deadline.Equal(requestDeadline) {
					t.Fatalf("deadline = %v, want request deadline %v", deadline, requestDeadline)
				}
			}
			if !errors.Is(mock.errAtReturn, testCase.wantContextError) {
				t.Fatalf("database context error = %v, want %v", mock.errAtReturn, testCase.wantContextError)
			}
			if mock.ctx.Err() == nil {
				t.Fatal("readiness did not release its context after returning")
			}
		})
	}
}

func newHealthRouter(database *mockDatabase) *gin.Engine {
	gin.SetMode(gin.TestMode)
	var pinger health.DatabasePinger
	if database != nil {
		pinger = database
	}
	router := gin.New()
	routes.RegisterRoutes(router, routes.Dependencies{Health: health.NewAPI(pinger)})
	return router
}

func performHealthRequest(ctx context.Context, router *gin.Engine, path string) *httptest.ResponseRecorder {
	response := httptest.NewRecorder()
	router.ServeHTTP(response, httptest.NewRequestWithContext(ctx, http.MethodGet, path, nil))
	return response
}

func assertHealthResponse(t *testing.T, response *httptest.ResponseRecorder, wantHTTPStatus int, wantStatus string) {
	t.Helper()
	if response.Code != wantHTTPStatus {
		t.Fatalf("HTTP status = %d, want %d; body = %s", response.Code, wantHTTPStatus, response.Body.String())
	}
	var payload healthResponse
	decoder := json.NewDecoder(response.Body)
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(&payload); err != nil {
		t.Fatal(err)
	}
	if payload.Status != wantStatus {
		t.Fatalf("status = %q, want %q", payload.Status, wantStatus)
	}
	if response.Header().Get("Cache-Control") != "no-store" {
		t.Fatal("health response must disable caching")
	}
}

type mockDatabase struct {
	err                 error
	waitForCancellation bool
	called              bool
	ctx                 context.Context
	started             time.Time
	errAtReturn         error
}

func (database *mockDatabase) PingContext(ctx context.Context) error {
	database.called = true
	database.ctx = ctx
	database.started = time.Now()
	if database.waitForCancellation {
		select {
		case <-ctx.Done():
		case <-time.After(3 * testReadinessTimeout):
			return errors.New("readiness did not cancel the database check")
		}
	}
	database.errAtReturn = ctx.Err()
	if database.errAtReturn != nil {
		return database.errAtReturn
	}
	return database.err
}
